(7051414, 1072221, 30712, '<td valign="top">A great range of colour throughout the image.  It creates a really dramatic effect.</td>', 'A great range of colour throughout the image.  It creates a really dramatic effect.', '2013-06-12 05:02:19.000000', NULL, 1),
(7051415, 1072377, 30712, '<td valign="top">I like the moody colour.  It gives a sense of the unreal.</td>', 'I like the moody colour.  It gives a sense of the unreal.', '2013-06-12 05:03:31.000000', NULL, 1),
(7051418, 1072378, 81362, '<td valign="top">Gothic feeling. Nice framing of the sky.</td>', 'Gothic feeling. Nice framing of the sky.', '2013-06-12 05:35:29.000000', NULL, 1),
(7051419, 1072221, 81362, '<td valign="top">Pretty colors, peaceful mood.</td>', 'Pretty colors, peaceful mood.', '2013-06-12 05:36:05.000000', NULL, 1),
(7051422, 1072279, 81362, '<td valign="top">I like having the bit of ambient world (streetlight perhaps?) included to contrast with the sky.</td>', 'I like having the bit of ambient world (streetlight perhaps?) included to contrast with the sky.', '2013-06-12 05:39:57.000000', NULL, 1),
(7051423, 1072281, 81362, '<td valign="top">Shades of blue give a soothing feeling.</td>', 'Shades of blue give a soothing feeling.', '2013-06-12 05:43:00.000000', NULL, 1),
(7051425, 1072373, 81362, '<td valign="top">Good title, nice composition. Light on in the window and contrast of blurred moving clouds with stable house sets up potential narrative. Glad you were able to include some stars. Should score well.</td>', 'Good title, nice composition. Light on in the window and contrast of blurred moving clouds with stable house sets up potential narrative. Glad you were able to include some stars. Should score well.', '2013-06-12 05:47:04.000000', NULL, 1),
(7051428, 1072372, 81362, '<td valign="top">Good choice to include the tree tops and house.</td>', 'Good choice to include the tree tops and house.', '2013-06-12 05:49:29.000000', NULL, 1),
(7051432, 1072375, 81362, '<td valign="top">Sky with clouds and stars against transmission towers and trees lovely. Mixed thoughts about including the road action -- takes away from the simplicity of the sky composition, but adds color and sense of action that makes it more lively than the average sky-scape.</td>', 'Sky with clouds and stars against transmission towers and trees lovely. Mixed thoughts about including the road action -- takes away from the simplicity of the sky composition, but adds color and sense of action that makes it more lively than the average sky-scape.', '2013-06-12 05:54:09.000000', NULL, 1),
(7051436, 1072369, 81362, '<td valign="top">Noise/grain lends impression of being taken through irregular glass like a shower door, an interesting effect.</td>', 'Noise/grain lends impression of being taken through irregular glass like a shower door, an interesting effect.', '2013-06-12 05:57:22.000000', NULL, 1),
(7051438, 1072135, 81362, '<td valign="top">Enjoying the stars a lot here. Many areas did not have the luxury of clear sky during the challenge week.</td>', 'Enjoying the stars a lot here. Many areas did not have the luxury of clear sky during the challenge week.', '2013-06-12 05:59:26.000000', NULL, 1),
