(7051442, 1072335, 81362, '<td valign="top">Very subtle, an abstract worth pausing to contemplate.</td>', 'Very subtle, an abstract worth pausing to contemplate.', '2013-06-12 06:05:27.000000', NULL, 1),
(7051443, 1072277, 81362, '<td valign="top">Windmill lends good additional emphasis to the sense of motion.</td>', 'Windmill lends good additional emphasis to the sense of motion.', '2013-06-12 06:06:48.000000', NULL, 1),
(7051444, 1072378, 118154, '<td valign="top">Nice image,not so keen on the title.</td>', 'Nice image,not so keen on the title.', '2013-06-12 06:13:44.000000', NULL, 1),
