(7053002, 1072281, 128323, '<td valign="top">As window shots go, this is definitely a keeper!  Beautiful!</td>', 'As window shots go, this is definitely a keeper!  Beautiful!', '2013-06-18 05:53:59.000000', NULL, 1),
(7053003, 1072284, 128323, '<td valign="top">I think this would have turned out a little better with a longer shutter speed, although it looks like you were battling with some civilization lights in the distance.  Nice shot though!</td>', 'I think this would have turned out a little better with a longer shutter speed, although it looks like you were battling with some civilization lights in the distance.  Nice shot though!', '2013-06-18 05:55:13.000000', NULL, 1),
(7053004, 1072327, 128323, '<td valign="top">I''m curious to know how you only got those big dipper stars to streak like that--nice shot!</td>', 'I''m curious to know how you only got those big dipper stars to streak like that--nice shot!', '2013-06-18 05:56:11.000000', NULL, 1),
(7053005, 1072277, 128323, '<td valign="top">Nice dreamy effect.</td>', 'Nice dreamy effect.', '2013-06-18 05:56:34.000000', NULL, 1),
(7053006, 1072374, 128323, '<td valign="top">I think if your WB was set to tungsten it would have turned out a little better.  The lights below have a bit of a harsh yellow tone on the horizon.</td>', 'I think if your WB was set to tungsten it would have turned out a little better.  The lights below have a bit of a harsh yellow tone on the horizon.', '2013-06-18 05:57:17.000000', NULL, 1),
