(7053269, 1072295, 68020, '<td valign="top">Woohoo! Congrats brother!</td>', 'Woohoo! Congrats brother!', '2013-06-19 01:31:02.000000', NULL, 0),
(7053270, 1072278, 155094, '<td valign="top">Thank you to everyone. Big thank you to Andrew, my first ribbon, I am so excited. Before the challenge Andrew and I had made plans to shoot night skies, we researched the topic and made our plans, to travel into the country to avoid city lights. The day before had to change plans as weather was changing. I used " Rule 500 " that is to shoot with 24mm lens at 20 seconds with a full frame camera. Manual focus to infinity at ISO 3200 with a trigger release. Andrew held the lantern. I forgot to set the Noise reduction in the excitement of the moment. Wow this is great.</td>', 'Thank you to everyone. Big thank you to Andrew, my first ribbon, I am so excited. Before the challenge Andrew and I had made plans to shoot night skies, we researched the topic and made our plans, to travel into the country to avoid city lights. The day before had to change plans as weather was changing. I used " Rule 500 " that is to shoot with 24mm lens at 20 seconds with a full frame camera. Manual focus to infinity at ISO 3200 with a trigger release. Andrew held the lantern. I forgot to set the Noise reduction in the excitement of the moment. Wow this is great.', '2013-06-19 01:32:51.000000', NULL, 0),
(7053271, 1072221, 68020, '<td valign="top">Wow! Great score for an awesome shot!! Congrats Dennis! So there is not one, not two, but three Long Shots in the top ten!! :-)</td>', 'Wow! Great score for an awesome shot!! Congrats Dennis! So there is not one, not two, but three Long Shots in the top ten!! :-)', '2013-06-19 01:37:28.000000', NULL, 0),
