(7053303, 1072372, 109387, '<td valign="top">Congrats on the TT man! Nice one for a last minute entry ;)</td>', 'Congrats on the TT man! Nice one for a last minute entry ;)', '2013-06-19 05:37:17.000000', NULL, 0),
(7053304, 1072295, 12611, '<td valign="top">Nice work. Congrats.</td>', 'Nice work. Congrats.', '2013-06-19 06:08:13.000000', NULL, 0),
(7053305, 1072221, 12611, '<td valign="top">Excellent shot. Congrats Dennis.</td>', 'Excellent shot. Congrats Dennis.', '2013-06-19 06:11:15.000000', NULL, 0),
(7053311, 1072221, 33736, '<td valign="top">Beyond admiring this beautiful picture, I''m admiring you for sharing so much information. Why other photographers don''t do so is a mystery to me.  Why is it so difficult to at least identify the location of a scene (or the name of a building)?<br/> <br/>You, however, took us on your journey and truly shared your experience.  For that alone, I would have given you the Blue! Congratulations for a truly winning photograph.</td>', 'Beyond admiring this beautiful picture, I''m admiring you for sharing so much information. Why other photographers don''t do so is a mystery to me.  Why is it so difficult to at least identify the location of a scene (or the name of a building)? You, however, took us on your journey and truly shared your experience.  For that alone, I would have given you the Blue! Congratulations for a truly winning photograph.', '2013-06-19 07:22:20.000000', NULL, 0),
(7053312, 1072221, 33736, '<td valign="top">Beyond admiring this beautiful picture, I''m admiring you for sharing so much information. Why other photographers don''t do so is a mystery to me.  Why is it so difficult to at least identify the location of a scene (or the name of a building)?<br/> <br/>You, however, took us on your journey and truly shared your experience.  For that alone, I would have given you the Blue! Congratulations for a truly winning photograph.</td>', 'Beyond admiring this beautiful picture, I''m admiring you for sharing so much information. Why other photographers don''t do so is a mystery to me.  Why is it so difficult to at least identify the location of a scene (or the name of a building)? You, however, took us on your journey and truly shared your experience.  For that alone, I would have given you the Blue! Congratulations for a truly winning photograph.', '2013-06-19 07:22:20.000000', NULL, 0),
(7053331, 1072373, 19825, '<td valign="top">The world is spinning while we sit at home with our TV and AC. Nice shot.</td>', 'The world is spinning while we sit at home with our TV and AC. Nice shot.', '2013-06-19 10:12:51.000000', NULL, 0),
(7053334, 1072221, 61089, '<td valign="top">As you can see on this link, June 7 was a pretty ACTIVE day for the Aurora.  Go to the Aurora Forecast/Geophysical Institute and use the back button (or previous button) to go back to June 7 2013.<br/> <br/>  I am not surprised that the camera was able to detect it this far south  Great shot</td>', 'As you can see on this link, June 7 was a pretty ACTIVE day for the Aurora.  Go to the Aurora Forecast/Geophysical Institute and use the back button (or previous button) to go back to June 7 2013.   I am not surprised that the camera was able to detect it this far south  Great shot', '2013-06-19 10:18:57.000000', NULL, 0),
(7053350, 1072221, 112739, '<td valign="top">Thanks <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/31_N.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/31_N.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/31_N.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=61089" rel="nofollow" target="_blank">phylvince</a> for the information. I assumed that was the case, but did not take time to research it. Could not see it with my eyes while shooting the scene and only discovered it once I uploaded the images. Very interesting.</td>', 'Thanks  phylvince for the information. I assumed that was the case, but did not take time to research it. Could not see it with my eyes while shooting the scene and only discovered it once I uploaded the images. Very interesting.', '2013-06-19 11:17:30.000000', NULL, 0),
(7053352, 1072278, 112739, '<td valign="top">Wonderfully dramatic image. Congratulations on the Red ribbon!</td>', 'Wonderfully dramatic image. Congratulations on the Red ribbon!', '2013-06-19 11:20:00.000000', NULL, 0),
